package com.dexm.personajes.adapter.out.persistence;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
public class CharacterEntity {
 private String id; private String importSourceId; private String name; private String campaignId; private String ownerUserId; private String imageUrl; private int experience; private int level; private int evolutionPoints; private int geneticsPoints; private String uniqueAbilityDecisionsJson = "{}"; private boolean closed; private String attributesJson; private String geneticsJson; private String creationMode = "empty"; private String race; private boolean einherjer = true; private boolean awakened; private String einherjerOrigin; private Integer startingAge; private Integer awakeningAge; private Integer sheetAge; private String selectedMajorAttributesJson = "[]"; private String creationWizardState = "empty"; private List<String> editorEmails = new ArrayList<>(); private boolean editorEmailsConfigured; private Instant createdAt; private Instant updatedAt;
 protected CharacterEntity(){} public CharacterEntity(String id,String name,int experience,String attributesJson,String geneticsJson){this(id,null,name,null,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,String attributesJson,String geneticsJson){this(id,campaignId,name,imageUrl,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,int level,String attributesJson,String geneticsJson){this.id=id;this.campaignId=campaignId;this.name=name;this.imageUrl=imageUrl;this.experience=experience;this.level=level;this.attributesJson=attributesJson;this.geneticsJson=geneticsJson;this.editorEmailsConfigured=true;this.createdAt=Instant.now();this.updatedAt=this.createdAt;}
 public String getId(){return id;} public String getImportSourceId(){return importSourceId;} public void setImportSourceId(String v){importSourceId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCampaignId(){return campaignId;} public String getOwnerUserId(){return ownerUserId;} public void setOwnerUserId(String v){ownerUserId=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public int getExperience(){return experience;} public void setExperience(int v){experience=v;} public int getLevel(){return level;} public void setLevel(int v){level=Math.max(1,v);} public int getEvolutionPoints(){return evolutionPoints;} public void setEvolutionPoints(int v){evolutionPoints=Math.max(0,v);} public int getGeneticsPoints(){return geneticsPoints;} public void setGeneticsPoints(int v){geneticsPoints=Math.max(0,v);} public String getUniqueAbilityDecisionsJson(){return uniqueAbilityDecisionsJson;} public void setUniqueAbilityDecisionsJson(String v){uniqueAbilityDecisionsJson=v == null ? "{}" : v;} public boolean isClosed(){return closed;} public void setClosed(boolean v){closed=v;} public String getAttributesJson(){return attributesJson;} public void setAttributesJson(String v){attributesJson=v;} public String getGeneticsJson(){return geneticsJson;} public void setGeneticsJson(String v){geneticsJson=v;} public String getCreationMode(){return creationMode;} public void setCreationMode(String v){creationMode=v;} public String getRace(){return race;} public void setRace(String v){race=v;} public boolean isEinherjer(){return einherjer;} public void setEinherjer(boolean v){einherjer=v;} public boolean isAwakened(){return awakened;} public void setAwakened(boolean v){awakened=v;} public String getSelectedMajorAttributesJson(){return selectedMajorAttributesJson;} public void setSelectedMajorAttributesJson(String v){selectedMajorAttributesJson=v == null ? "[]" : v;} public String getCreationWizardState(){return creationWizardState;} public void setCreationWizardState(String v){creationWizardState=v;} public String getEinherjerOrigin(){return einherjerOrigin;} public void setEinherjerOrigin(String v){einherjerOrigin=v;} public Integer getStartingAge(){return startingAge;} public void setStartingAge(Integer v){startingAge=v;} public Integer getAwakeningAge(){return awakeningAge;} public void setAwakeningAge(Integer v){awakeningAge=v;} public Integer getSheetAge(){return sheetAge;} public void setSheetAge(Integer v){sheetAge=v;} public List<String> getEditorEmails(){if(editorEmails==null) editorEmails=new ArrayList<>(); return editorEmails;} public void setEditorEmails(Collection<String> values){editorEmails=new ArrayList<>(normalizeEmails(values)); editorEmailsConfigured=true;} public boolean isEditorEmailsConfigured(){return editorEmailsConfigured;} public void setEditorEmailsConfigured(boolean value){editorEmailsConfigured=value;} public void addEditorEmail(String email){editorEmailsConfigured=true; var normalized=normalizeEmail(email); if(!normalized.isBlank()&&!getEditorEmails().contains(normalized)) editorEmails.add(normalized);} public void removeEditorEmail(String email){editorEmailsConfigured=true; getEditorEmails().remove(normalizeEmail(email));} public boolean hasEditorEmail(String email){return getEditorEmails().contains(normalizeEmail(email));} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();}
 private static List<String> normalizeEmails(Collection<String> values){var result=new LinkedHashSet<String>(); if(values!=null) for(var value:values){var normalized=normalizeEmail(value); if(!normalized.isBlank()) result.add(normalized);} return new ArrayList<>(result);}
 private static String normalizeEmail(String email){return email==null?"":email.trim().toLowerCase(Locale.ROOT);}
}

